#!/usr/bin/env bash
# Forgeline deterministic gate. Runs in the job worktree. Exit 0 = pass. No AI involved.
# Generated by `forgeline init`; edit freely, it belongs to your repo now.
# Env: FACTORY_BASE (base branch), FACTORY_AREAS (comma list), FACTORY_JOB.
set -euo pipefail

has_area() { [[ -z "${FACTORY_AREAS:-}" || ",${FACTORY_AREAS}," == *",$1,"* ]]; }
step() { printf '\n==> %s\n' "$*"; }
have() { command -v "$1" >/dev/null 2>&1; }
